import { Plugin } from "@opencode/plugin"
import { execFileSync } from "node:child_process"

// Generated by install.py. Never interpolate untrusted text into shell commands.
const RUNNER = "/usr/local/libexec/opencode-agentic/agentic_gate.py"
const PROJECT = "/home/kosumosu/dev/own/opencode-agentic-lab"

function guard(...args: string[]): string {
  try {
    return execFileSync("/usr/bin/python3", [RUNNER, "--project", PROJECT, ...args], {
      encoding: "utf8", timeout: 1_800_000, maxBuffer: 4 * 1024 * 1024,
      stdio: ["ignore", "pipe", "pipe"],
    }).trim()
  } catch (err: any) {
    const details = String(err?.stderr ?? err?.message ?? err)
    throw new Error(`Agentic workflow blocked: ${details}`)
  }
}

export default Plugin.define({
  id: "agentic.workflow",
  async setup(ctx) {
    // Guards reviewer even if it is selected manually, not just through /review.
    await ctx.session.hook("context", (event: any) => {
      const agent = typeof event.agent === "string" ? event.agent : event.agent?.id
      if (agent === "reviewer") {
        try { guard("ready", "verify") } catch { guard("ready", "full") }
      }
    })

    await ctx.command.transform((editor) => {
      editor.add({
        name: "design",
        description: "Architect: design into unapproved draft files",
        execute: async ({ sessionID, prompt, delivery }) => {
          await ctx.session.switchAgent({ sessionID, agent: "architect" })
          await ctx.session.switchModel({ sessionID, model: { providerID: "openai", id: "gpt-5.6-sol" } })
          await ctx.session.prompt({ ...prompt, sessionID, delivery,
            text: `Проектирование задачи: ${prompt.text}\n\nСохрани черновики ТОЛЬКО в .agentic/drafts/spec.md и .agentic/drafts/plan.md. Укажи acceptance criteria и тест-план, статус DRAFT. Не меняй код. Не утверждай проект самостоятельно.` })
        },
      })
      editor.add({
        name: "approve",
        description: "Human approves current draft, creates baseline",
        execute: async ({ sessionID }) => {
          const result = guard("approve", "--human-confirm")
          await ctx.session.synthetic({ sessionID, text: `Human approval recorded. ${result}` })
        },
      })
      editor.add({
        name: "implement",
        description: "Developer: ub-mode + TDD + auto-gates",
        execute: async ({ sessionID, prompt, delivery }) => {
          guard("check-approval")
          await ctx.session.switchAgent({ sessionID, agent: "developer" })
          await ctx.session.switchModel({ sessionID, model: { providerID: "opencode", id: "deepseek-v4.1-flash-free" } })
          await ctx.session.prompt({ ...prompt, sessionID, delivery,
            text: `Реализуй утверждённую спецификацию через оригинальный ub-mode. Сначала загрузка skill, затем TDD RED→GREEN→REFACTOR с реальными запусками тестов; после каждого логического блока запуск fast-gate. Не меняй утверждённые specs/plans или конфигурацию проверок. Итоговый quality gate: /usr/bin/python3 ${RUNNER} --project ${PROJECT} gate fast. Задача: ${prompt.text}. Не выполняй push/deploy. При невозможности тестов явно сообщи причину.` })
        },
      })
      editor.add({
        name: "review",
        description: "Mandatory fresh verify gate before independent AI review",
        execute: async ({ sessionID, prompt, delivery }) => {
          guard("gate", "verify") // throws BEFORE reviewer is invoked
          await ctx.session.switchAgent({ sessionID, agent: "reviewer" })
          await ctx.session.switchModel({ sessionID, model: { providerID: "openai", id: "gpt-5.6-sol" } })
          await ctx.session.prompt({ ...prompt, sessionID, delivery,
            text: `Независимое ревью утверждённых acceptance criteria, архитектуры, безопасности и тестов. Verify Gate только что прошёл. Укажи конкретные дефекты по пути/строке, приоритету и доказательствам. Не изменяй код. Контекст запроса: ${prompt.text}` })
        },
      })
      editor.add({
        name: "finalize",
        description: "Mandatory fresh FULL gate + final human acceptance",
        execute: async ({ sessionID, prompt, delivery }) => {
          guard("gate", "full") // expensive full suite
          await ctx.session.switchAgent({ sessionID, agent: "reviewer" })
          await ctx.session.switchModel({ sessionID, model: { providerID: "openai", id: "gpt-5.6-sol" } })
          await ctx.session.prompt({ ...prompt, sessionID, delivery,
            text: `FULL Quality Gate успешно выполнен. Подготовь финальное заключение: результаты, ограничения, открытые замечания, критерии приёмки. Ничего не изменяй и не выполняй push/deploy. Окончательное принятие решения принадлежит человеку. Дополнительный контекст: ${prompt.text}` })
        },
      })
    })
  },
})
